@Component("metric-handler")
@ProcessingGroup("metric-processing-group")
public class MetricEventHandler {
	
	// core constructor
	MetricEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateMetricEvent
     */
    @EventHandler
    public void handle( CreateMetricEvent event) {
        entityManager.persist(new Metric(event.getMetricId(), event.getName(), event.getExpression(), event.getUnit(), event.getSemanticModel(), event.getDatasets(), event.getGlossaryTerms(), event.getAlerts(), event.getVisualizations(), event.getMetricType()));
    }

    /*
     * @param	event UpdateMetricEvent
     */
    @EventHandler
    public Metric handle( UpdateMetricEvent event) {
    	entityManager.merge(new Metric(event.getMetricId(), event.getName(), event.getExpression(), event.getUnit(), event.getSemanticModel(), event.getDatasets(), event.getGlossaryTerms(), event.getAlerts(), event.getVisualizations(), event.getMetricType()));
    }
    
    /*
     * @param	event DeleteMetricEvent
     */
    @EventHandler
    public void on( DeleteMetricEvent event) {
    	Metric entity = new Metric();
   
    	// ------------------------------------------
    	// apply the MetricId
    	// ------------------------------------------
    	entity.setMetricId( event.getMetricId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final MetricRepository metricEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(MetricEventHandler.class.getName());

}
